export const lsPurvaVersesEn: any[] = [
  { id: "ls-purva-m01", number: "Pūrva-maṅgala 1", section: "Pūrva-pīṭhikā · Maṅgala", iast: "mātaḥ śrīlalite prasīda lauhityanirjita japākusumānurāgāṁ pāśāṅkuśau dhanuriṣūnapi dhārayantīm । tāmrekṣaṇāmaruṇamālyaviśeṣabhūṣāṁ tāmbūlapūritamukhīṁ tripurāṁ namāmi", translation: "Good mother resplendent as Lalita, the rosy one, favour us: caught red beyond the red of hibiscus, her four hands loop and goad and bow and shafts; half-open gaze, ruddy blooms, mouth full of betel: hear Tripura.", commentary: "The verse invokes the Mother as a visible deity of mercy under a red sun: delicate, honeyed, fierce in instruments, lavish in red garland. That she is prayed to before the prose of the frame gives access to the entire work: the thousand epithets are the body of the deity imagined here in luminous red. For practice the image steadies attention on Tripura before study, so recitation is worship rather than bare enumeration.", keyPoints: ["Invocation of Lalita as red Tripura", "Four emblems named before the hymn", "Sets a devotional gaze for recitation"] },
  { id: "ls-purva-m02", number: "Pūrva-maṅgala 2", section: "Pūrva-pīṭhikā · Maṅgala", iast: "madhurānmadhurā mahitānmahitā mṛdulānmṛdulā sulabhātsulabhā । aruṇādaruṇā sadayātsadayā lalitāllalitā lalitā’vatu mām", translation: "She is sweeter than sweet, greater than great, tender beyond tender, accessible beyond easy; redder than red, kinder than kind, lovelier than love: may Lalita protect me.", commentary: "This benediction piles comparatives until language surrenders, asserting that Lalita exceeds every measure of sweetness, greatness, tenderness, access, radiance, and compassion. Placed second, it turns praise into request for protection, making grace the precondition of the difficult text ahead. Doctrinally it presents the Goddess as both transcendent and readily reachable, so the devotee approaches the thousand names with confidence rather than fear.", keyPoints: ["Superlatives declare Lalita beyond measure", "Protection sought before the teaching", "Grace joined to approachability"] },
  { id: "ls-purva-m03", number: "Pūrva-maṅgala 3", section: "Pūrva-pīṭhikā · Maṅgala", iast: "lalitaṁ caraṇasaroje lalitataraṁ vadanaśītarucibimbe । lalitatamaṁ smitarociṣi lalitākhyaṁ vasatu me purataḥ", translation: "Lovely in the lotus feet, lovelier in the moonlike face, loveliest in the radiance of her smile: may the One called Lalita stand before me.", commentary: "The verse grades loveliness upward from feet to face to smile, drawing the meditator closer until the Goddess stands present before the mind. As a mangala it converts abstract reverence into intimate encounter, promising nearness rather than distant majesty. For practice it teaches sequential visualization, resting attention on successive centers of beauty so that remembrance becomes vivid and continuous during repetition of the names.", keyPoints: ["Graded beauty from feet to smile", "Presence invoked before the mind", "Visualization as preparation for japa"] },
  { id: "ls-purva-m04", number: "Pūrva-maṅgala 4", section: "Pūrva-pīṭhikā · Maṅgala", iast: "tvatprasūtastvadājñaptastvaddāsastvatparāyaṇaḥ । tvannāmacintanaparastvadarthe’haṁ niyojitaḥ", translation: "Born from you, commanded by you, your servant, devoted to you alone; absorbed in remembering your names, I am appointed to your service.", commentary: "The speaker offers himself as wholly derived from the Goddess: origin, order, servitude, refuge, and mental occupation all belong to her. In the frame this self-dedication authorizes the editorial labour of compiling and explaining the hymn, disclaiming personal authorship entirely. Practically it models the reciter's attitude, that study and chanting succeed only when undertaken as assigned service rather than self-display.", keyPoints: ["Total self-offering to the Goddess", "Compiler claims no independent authorship", "Recitation framed as appointed service"] },
  { id: "ls-purva-m05", number: "Pūrva-maṅgala 5", section: "Pūrva-pīṭhikā · Maṅgala", iast: "tvayārjitamidaṁ sarvaṁ tava svaṁ parameśvari । tvadadhīnaṁ karomīha tvadarthe tanniyojaye", translation: "Whatever is earned here is earned by you; all is your own, O supreme Lady. I place it under your control and employ it for your purpose.", commentary: "This verse surrenders the fruit of all effort, declaring wealth, merit, and even the present work to be her property held in trust. It completes the inward offering of the previous verse with an outward one, removing possessiveness from religious action. As discipline it teaches that the merit of chanting the thousand names should be redirected to her, which guards the practitioner against pride and bargaining.", keyPoints: ["All gains acknowledged as hers", "Merit placed under her disposal", "Antidote to pride in worship"] },
  { id: "ls-purva-m06", number: "Pūrva-maṅgala 6", section: "Pūrva-pīṭhikā · Maṅgala", iast: "tava devi vaśe varte tavājñāmeva pālayan । tava nāmāni gaṇayan tvayi līye gṛhāṇa mām", translation: "O Goddess, I move within your power, keeping only your command; counting your names, may I dissolve in you. Receive me.", commentary: "The prayer asks not for boons but for absorption: life governed by her order, speech occupied with her names, ending in dissolution within her. It states the culminating aim of namasahasra practice in miniature, where repetition passes into identity. For the reciter it sets intention correctly, that each name counted should loosen separateness until the counter rests in the Goddess herself.", keyPoints: ["Life bound to her command alone", "Counting names aimed at dissolution", "Union stated as the goal of japa"] },
  { id: "ls-purva-m07", number: "Pūrva-maṅgala 7", section: "Pūrva-pīṭhikā · Maṅgala", iast: "eṣā bhaktyā tava viracitā yā devi sevā svīkṛtyaināṁ sapadi sakalānme’parādhān kṣamasva । nyūnaṁ yattattava karuṇayā pūrṇatāmetu sadyaḥ sānandaṁ me hṛdayakamale te’stu nityaṁ nivāsaḥ", translation: "O Goddess, accept this service I have made with devotion; forgive at once all my faults in it. What is lacking, make full by your compassion, and dwell ever joyfully in my heart's lotus.", commentary: "The closing mangala begs pardon for defects in worship and asks her compassionate grace to supply what is missing, ending with a request for her constant residence in the heart. It seals the preliminaries with humility, acknowledging that no hymn or rite is flawless. Practically it teaches kshamapana, that every recitation should end in confession and invitation, leaving the heart as her seat rather than claiming completion.", keyPoints: ["Acceptance and pardon requested", "Grace completes imperfect worship", "Heart offered as her dwelling"] },
  { id: "ls-purva-g01", number: "Pūrva-guru 1", section: "Pūrva-pīṭhikā · Guru & Paribhāṣā", iast: "gururbrahmā gururviṣṇuḥ gururdevo maheśvaraḥ । guruḥ sākṣātparaṁ brahma tasmai śrīgurave namaḥ", translation: "The guru is Brahma, the guru is Vishnu, the guru is the god Maheshvara; the guru is the supreme brahman in person. Salutation to that glorious guru.", commentary: "This celebrated salutation identifies the teacher with the three cosmic functions and with ultimate reality itself, grounding the entire transmission in the guru principle. Placed before the Lalita teaching, it reminds hearers that the thousand names reach them only through an authorized revealer. For practice it enjoins bowing to the teacher first, since mantra and meaning remain inert without the living instruction that awakens them.", keyPoints: ["Guru equated with cosmic powers", "Transmission depends on the teacher", "Salutation precedes mantra study"] },
  { id: "ls-purva-g02", number: "Pūrva-guru 2", section: "Pūrva-pīṭhikā · Guru & Paribhāṣā", iast: "vande gurupadadvandvamavāṅmanasagocaram । raktaśuklaprabhāmiśraṁ atarkyaṁ traipuraṁ mahaḥ", translation: "I revere the pair of the guru's feet, beyond speech and mind, a splendour of Tripura mingled red and white, beyond reckoning.", commentary: "The verse bows to the guru's feet as a reality inaccessible to thought and words, glowing with the red-white radiance associated with Tripura. It shifts reverence from the guru's person to the mysterious power present at his feet. Doctrinally it points to grace as suprarational, while practically it directs the disciple to meditate on that contact point of lineage power before approaching the Goddess herself.", keyPoints: ["Guru's feet as suprarational splendour", "Red-white glow of Tripura", "Grace approached through surrender"] },
  { id: "ls-purva-g03", number: "Pūrva-guru 3", section: "Pūrva-pīṭhikā · Guru & Paribhāṣā", iast: "śuklāmbaradharaṁ viṣṇuṁ śaśivarṇaṁ caturbhujam । prasannavadanaṁ vande sarvavighnopaśāntaye", translation: "Clad in white, all-pervading, moon-hued, four-armed, of gracious face: I revere Vishnu for the stilling of all obstructions.", commentary: "This obstacle-removing salutation to white-clad Vishnu is traditionally placed at undertakings so that study proceeds unhindered. Its calm lunar imagery counterbalances the fiery redness of Lalita, invoking preservation and clarity at the threshold. In practice it teaches beginning sacred work with a prayer for removal of outer and inner impediments, so attention can rest undivided on the thousand names. It also harmonizes Vaishnava and Shakta devotion, showing that one Goddess is served when all benevolent powers are honoured first.", keyPoints: ["Vishnu invoked as remover of obstacles", "White lunar calm at the outset", "Unimpeded study sought first"] },
  { id: "ls-purva-p01", number: "Pūrva-paribhāṣā 1", section: "Pūrva-pīṭhikā · Guru & Paribhāṣā", iast: "tripurāṁ kulanidhimīḍe’ruṇaśriyaṁ kāmarājaviddhāṅgīm । triguṇairdevairvinutāmekāntāṁ bindugāṁ mahārambhām", translation: "I praise Tripura, treasury of the clan, rich with dawn-red splendour, her limbs pierced by the god of desire's arrows; adored by gods of the three qualities, solitary, abiding in the point, she undertakes the great beginning.", commentary: "This dense paribhasha verse condenses technical doctrine into praise: Tripura as repository of Kaula power, red with creative energy, struck by love yet beyond the gunas, dwelling solitary in the bindu. It functions as a seed-summary of the metaphysics presupposed by the hymn. For the initiated it signals that the names ahead encode mantra-shastra and Srichakra symbolism, not mere poetry.", keyPoints: ["Tripura praised as clan treasury", "Bindu-dwelling beyond the gunas", "Signals esoteric code in the names"] },
  { id: "ls-purva-p02", number: "Pūrva-paribhāṣā 2", section: "Pūrva-pīṭhikā · Guru & Paribhāṣā", iast: "lalitānāmasahasre chalārṇasūtrānuyāyinyaḥ । paribhāṣā bhāṣyante saṅkṣepātkaulikapramodāya", translation: "In the thousand names of Lalita there are covert letter-threads running through; the technical keys are stated briefly, for the delight of the Kaula knowers.", commentary: "The verse announces that the hymn contains hidden alphabetic and mantric patterns and promises a concise key for qualified readers. It frames the paribhasha section as an interpretive aid rather than ordinary commentary. Practically it warns that full meaning unfolds only with knowledge of mantra convention, while inviting properly prepared devotees to rejoice in uncovering those connections. Such brevity respects oral lineage, giving just enough for memory while leaving fuller exposition to the living teacher's explanation.", keyPoints: ["Hidden letter-patterns declared", "Brief key offered to initiates", "Meaning tied to mantra convention"] },
  { id: "ls-purva-p03", number: "Pūrva-paribhāṣā 3", section: "Pūrva-pīṭhikā · Guru & Paribhāṣā", iast: "pañcāśadeka ādau nāmasu sārdhadvyaśītiśatam । ṣaḍaśītiḥ sārdhānte sarve viṁśatiśatatrayaṁ ślokāḥ", translation: "At the start among the names are fifty-one, in the middle one hundred and eighty-two and a half, at the end eighty-six and a half; in all, three hundred verses of twenty.", commentary: "This metrical note records the distribution of names across verses and the total stanza count, guiding reciters through the long hymn's architecture. It assures completeness, that no portion may be omitted without breaking the count. For practice it aids pacing and division of recitation, letting devotees apportion daily portions while keeping the whole thousand in view. The half-counts reflect verses shared between sections, teaching reciters to pause mindfully at joints rather than rushing through boundaries.", keyPoints: ["Structural count of names given", "Guides complete recitation", "Aids division for daily practice"] },
  { id: "ls-purva-p04", number: "Pūrva-paribhāṣā 4", section: "Pūrva-pīṭhikā · Guru & Paribhāṣā", iast: "daśabhūḥ sārdhanṛpālā adhyuṣṭaṁ sārdhanavaṣaḍadhyuṣṭam । munisūtahayāmbāśvoktirdhyānamekena", translation: "Ten lands, kings with a half, the greatly heated, the greatly heated nine-six; the speech of sage, narrator, horse-necked one, and Mother, with meditation in one verse.", commentary: "This cryptic memorial verse tallies speakers and sections of the frame: sages, Suta, Hayagriva, and the Goddess, together with the meditation stanza. Though deliberately condensed, its purpose is mnemonic, fixing the dialogue structure in memory. For students it marks that the thousand names arrive through layered voices, each with distinct authority, crowned by contemplative focus. Its obscurity is intentional, rewarding study under guidance and reminding casual readers that counting itself can be a contemplative act.", keyPoints: ["Mnemonic for frame speakers", "Marks layered transmission voices", "Meditation verse counted with dialogue"] },
  { id: "ls-purva-01", number: "Pūrva 1", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "aśvānana mahābuddhe sarvaśāstraviśārada । kathitaṁ lalitādevyāḥ caritaṁ paramādbhutam", translation: "O horse-faced one, greatly wise, skilled in all sciences: you have told the supremely wondrous story of the goddess Lalita.", commentary: "Agastya asks: after listening at length, he addresses Hayagriva with honorifics and acknowledges the marvellous Lalita narrative already received. This opening courtesy establishes the disciple's attentiveness and the teacher's competence before raising the one missing topic. It models proper inquiry, that a new question should rest on grateful recollection of what has already been generously taught. For modern readers it demonstrates how traditional learning inventories prior teaching before advancing, keeping knowledge cumulative rather than fragmented.", keyPoints: ["Agastya honours Hayagriva's learning", "Prior Lalita story acknowledged", "Courteous opening to fresh inquiry"] },
  { id: "ls-purva-02", number: "Pūrva 2", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "pūrvaṁ prādurbhavo mātuḥ tataḥ paṭṭābhiṣecanam । bhaṇḍāsuravadhaścaiva vistareṇa tvayoditaḥ", translation: "First the Mother's emergence, then her anointing, and the slaying of Bhandasura: all this you have told at length.", commentary: "Agastya asks: he reviews the cosmogonic and martial episodes already covered, from manifestation through coronation to the demon's defeat. The summary proves he has followed the Brahmanda narrative closely and is not asking from ignorance. Doctrinally it places the thousand names after creation, sovereignty, and victory over obstruction, as the crown of the story rather than its preface. It also establishes the hymn's setting after cosmic restoration, so the names are heard as celebration of order regained through her power.", keyPoints: ["Mother's birth and anointing recalled", "Bhanda's slaying noted as told", "Names sought as crown of narrative"] },
  { id: "ls-purva-03", number: "Pūrva 3", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "varṇitaṁ śrīpuraṁ cāpi mahāvibhavavistaram । śrīmatpañcadaśākṣaryāḥ mahimā varṇitastathā", translation: "You have described Sripura too, of vast abundant glory, and likewise the greatness of the holy fifteen-syllabled mantra.", commentary: "Agastya asks: he names two further teachings already given, the splendour of her sacred city and the majesty of the Panchadashi. This shows his grounding in both sacred geography and mantra lore before he requests the hymn. For practice it links place, formula, and praise as three supports of worship, with only the third still withheld. The pairing shows that vision of her abode and mastery of her formula naturally precede love of her names in ordered spiritual ascent.", keyPoints: ["Sripura description acknowledged", "Fifteen-syllabled mantra noted", "Place and formula precede praise"] },
  { id: "ls-purva-04", number: "Pūrva 4", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "ṣoḍhānyāsādayo devyāḥ nyāsakhaṇḍe samīritāḥ । antaryāgakramaścaiva bahiryāgakramastathā", translation: "The sixfold placements and the rest of the Goddess were stated in the section on placements, and likewise the orders of inner and outer worship.", commentary: "Agastya asks: he recalls instruction in ritual embodiment through nyasas and in both interior and exterior modes of sacrifice. The verse displays his ritual preparation, proving he seeks the hymn not as substitute for discipline but as its fulfilment. It underscores that recitation belongs within a complete liturgical life of embodied installation and worship. Such placement affirms that body, breath, and gesture are consecrated first, so that later utterance of names arises from an already sanctified vessel.", keyPoints: ["Nyasa teachings recalled", "Inner and outer rites noted", "Ritual ground laid for the hymn"] },
  { id: "ls-purva-05", number: "Pūrva 5", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "mahāyāgākramaścāpi pūjākhaṇḍe samīritāḥ । puraścaraṇakhaṇḍe tu japalakṣaṇamīritam", translation: "The order of the great sacrifice was also stated in the section on worship, and in the section on preliminary practice the character of muttering was taught.", commentary: "Agastya asks: he completes his survey with the great yaga procedure and the science of japa from the purashcharana section. By listing these, he shows no limb of practice remains unknown except the Mother's own thousand names. The point is that mantra repetition taught in general now seeks its supreme textual object. This background assures that the coming hymn crowns disciplined repetition, not replacing method but giving method its most beloved voice.", keyPoints: ["Great sacrifice teaching recalled", "Japa science noted as received", "Supreme object of japa still missing"] },
  { id: "ls-purva-06", number: "Pūrva 6", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "homakhaṇḍe tvayā prokto homadravyavidhikramaḥ । cakrarājasya vidyāyāḥ śrīdevyā deśikānmanoḥ", translation: "In the section on oblation you declared the procedure for oblation substances, concerning the king of chakras, the lore, the holy Goddess, the teacher, and the mantra.", commentary: "Agastya asks: he specifies the homa instructions covering diagram, goddess, teacher, and formula with their material details. This precision confirms careful hearing and preserves the ritual context into which the hymn will fit. It reminds practitioners that praise flourishes alongside exact offering, uniting fire ritual with verbal adoration. Remembering these fire rites keeps devotion embodied, joining flame, diagram, and sound long before the thousand names are finally sung.", keyPoints: ["Homa materials and rule recalled", "Chakra, Goddess, teacher linked", "Fire rite joined to coming praise"] },
  { id: "ls-purva-07", number: "Pūrva 7", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "rahasyakhaṇḍe tādātmyaṁ parasparamudīritam । stotrakhaṇḍe bahuvidhāḥ stutayaḥ parikīrtitāḥ", translation: "In the secret section the mutual identity of the two was declared, and in the hymn section manifold praises were proclaimed.", commentary: "Agastya asks: he notes the revelation of non-difference in the esoteric portion and the many hymns already given elsewhere. The contrast sharpens his coming question, since abundance of other praises makes the absence of Lalita's own thousand names conspicuous. Doctrinally it distinguishes general eulogy from the specific name-body that embodies her most intimately. The remark reveals a deliberate pedagogy, moving from identity to multiplicity, so the one essence is known before its thousand facets shine.", keyPoints: ["Mutual identity teaching noted", "Many other hymns acknowledged", "Stage set for the missing hymn"] },
  { id: "ls-purva-08", number: "Pūrva 8", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "mantriṇīdaṇḍinīdevyoḥ prokte nāmasahasrake । na tu śrīlalitādevyāḥ proktaṁ nāmasahasrakam", translation: "The thousand names of the goddesses Mantrini and Dandini were proclaimed, but the thousand names of holy Lalita herself were not proclaimed.", commentary: "Agastya asks: he states plainly the single omission, that her two great ministers received name-hymns while the Empress herself did not. The verse is the pivot of the whole frame, converting survey into pointed question. It teaches that attendants' glories, however great, cannot satisfy longing for the sovereign Goddess herself. The ministers' precedence heightens expectancy, suggesting that the sovereign's own praise must surpass what has already been glorified.", keyPoints: ["Ministers' hymns contrasted", "Lalita's own hymn noted absent", "Central question of the frame posed"] },
  { id: "ls-purva-09", number: "Pūrva 9", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "tatra me saṁśayo jāto hayagrīva dayānidhe । kiṁ vā tvayā vismṛtaṁ tajjñātvā vā samupekṣitam", translation: "About this a doubt has arisen in me, O Hayagriva, ocean of compassion: did you forget it, or knowingly pass it over?", commentary: "Agastya asks: with reverent address he offers two possible explanations, forgetfulness or deliberate omission. The gentle dilemma avoids accusation while demanding clarity, honouring the teacher's compassion. It models how a disciple may press a sensitive point without irreverence, attributing silence either to human lapse or to hidden wisdom. Such framing protects the teacher's dignity while honestly naming confusion, a model for students who must question without diminishing reverence.", keyPoints: ["Doubt voiced with reverence", "Forgetfulness or design suggested", "Respectful pressure for an answer"] },
  { id: "ls-purva-10", number: "Pūrva 10", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "mama vā yogyatā nāsti śrotuṁ nāmasahasrakam । kimarthaṁ bhavatā noktaṁ tatra me kāraṇaṁ vada", translation: "Or am I unfit to hear the thousand names? Tell me the reason why it was not spoken by you.", commentary: "Agastya asks: he turns scrutiny upon himself, wondering whether his own unworthiness explains the silence, and begs for the cause. This self-questioning displays humility and readiness for eligibility requirements. For aspirants it introduces adhikara, that the highest teaching is disclosed only to the qualified and may be withheld otherwise. It thereby introduces graded instruction, where the highest mysteries await ripeness rather than being broadcast to every curious ear.", keyPoints: ["Self-fitness questioned humbly", "Reason for silence requested", "Principle of eligibility introduced"] },
  { id: "ls-purva-11", number: "Pūrva 11", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "iti pṛṣṭo hayagrīvo muninā kumbhajanmanā । prahṛṣṭo vacanaṁ prāha tāpasaṁ kumbhasambhavam", translation: "So questioned by the sage born from the pot, Hayagriva was delighted and spoke these words to the ascetic pitcher-born.", commentary: "Sūta narrates: he bridges the Naimisha and Kanchi settings, reporting Hayagriva's pleased response to Agastya's query. The delight signals that the question was welcome rather than intrusive, marking Agastya as worthy. Narratively it shifts voice from direct plea to reported teaching, authorizing what follows as compassionate disclosure. The double naming of the pitcher-born sage roots the scene in sacred biography, reminding hearers that great questions arise from famous austerities.", keyPoints: ["Suta bridges question and answer", "Hayagriva's delight noted", "Worthy inquiry welcomed"] },
  { id: "ls-purva-12", number: "Pūrva 12", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "lopāmudrāpate’gastya sāvadhānamanāḥ śṛṇu । nāmrāṁ sahasraṁ yannoktaṁ kāraṇaṁ tadvadāmi te", translation: "O husband of Lopamudra, Agastya, listen with attentive mind: I shall tell you the reason why the thousand names were not spoken.", commentary: "Hayagrīva answers: addressing Agastya by his wife's name to honour his household sanctity, he promises a deliberate explanation and demands focused hearing. The verse moves the dialogue from doubt to assured teaching. It cues practitioners that what follows concerns secrecy and fitness, requiring settled attention rather than casual curiosity. By naming lineage through Lopamudra, the teacher honours married wisdom, showing that householder sages also receive the supreme secret.", keyPoints: ["Agastya honourably addressed", "Attentive hearing demanded", "Reason for silence promised"] },
  { id: "ls-purva-13", number: "Pūrva 13", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "rahasyamiti matvā’haṁ noktavāṁste na cānyathā । punaśca pṛcchate bhaktyā tasmāttatte vadāmyaham", translation: "Considering it a secret, I did not speak it to you, nothing else; yet since you ask again with devotion, therefore I shall tell it to you.", commentary: "Hayagrīva answers: he denies neglect and attributes silence solely to the text's secrecy, then yields to persistent devotion. This establishes the balance between guarding esoterica and compassion toward the earnest seeker. It teaches that holy reserve protects the teaching, while repeated devout asking can open the teacher's heart. The reply balances firmness with tenderness, holding the boundary of secrecy while opening the door that devotion has duly knocked upon.", keyPoints: ["Silence explained as secrecy", "No other motive claimed", "Devout persistence opens teaching"] },
  { id: "ls-purva-14", number: "Pūrva 14", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "brūyācchiṣyāya bhaktāya rahasyamapi deśikaḥ । bhavatā na pradeyaṁ syādabhaktāya kadācana", translation: "A teacher should tell even a secret to a devoted pupil, but by you it must never at any time be given to the non-devout.", commentary: "Hayagrīva answers: he states the two-sided rule of transmission, free disclosure downward to devotion and strict restraint toward its absence, binding Agastya in turn. The verse founds the lineage ethic of the hymn. Practically it warns every recipient that possession entails responsibility to withhold from the irreverent. Agastya himself becomes a link, entrusted not only to receive but to guard, so every bearer of the hymn shares in its protection.", keyPoints: ["Secret allowed to devoted pupil", "Withholding from non-devout enjoined", "Lineage responsibility imposed"] },
  { id: "ls-purva-15", number: "Pūrva 15", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "na śaṭhāya na duṣṭāya nāviśvāsāya karhicit । śrīmātṛbhaktiyukttāya śrīvidyārājavedine", translation: "Never to the deceitful, never to the wicked, never at any time to the faithless; only to one endowed with devotion to the holy Mother, a knower of the kingly holy lore.", commentary: "Hayagrīva answers: he lists disqualified recipients and then the positive marks, devotion to the Mother joined to knowledge of Srividya. The exclusions protect the hymn from misuse and scorn. For practice it defines eligibility as moral integrity plus faith plus initiation, not mere intellectual interest. These strictures preserve the hymn's sanctity, ensuring its power flows through reverence rather than curiosity, commerce, or contention.", keyPoints: ["Unfit recipients explicitly barred", "Devotion and Srividya required", "Eligibility as moral and initiatory"] },
  { id: "ls-purva-16", number: "Pūrva 16", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "upāsakāya śuddhāya deyaṁ nāmasahasrakam । yāni nāmasahasrāṇi sadyaḥ siddhipradāni vai", translation: "To a pure worshipper should the thousand names be given, the thousand names that swiftly grant accomplishment and are true.", commentary: "Hayagrīva answers: he completes the eligibility portrait with purity and active worship, adding that these names are proven bestowers of swift fruition. The promise motivates restraint, since power demands containment. It assures sincere upasakas that the hymn is not inert praise but an effective means to swift spiritual attainment. Purity here means singleness of aim, a heart settled on the Mother, which alone can bear the rapid fruition these potent names confer.", keyPoints: ["Purity and worship required", "Swift accomplishment promised", "Hymn as effective means praised"] },
  { id: "ls-purva-17", number: "Pūrva 17", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "tantreṣu lalitādevyāsteṣu mukhyamidaṁ mune । śrīvidyaiva tu mantrāṇāṁ tatra kādiryathā parā", translation: "Among the tantras of the goddess Lalita these are the chief, O sage; even as among mantras the holy lore, wherein the Kadi is supreme.", commentary: "Hayagrīva answers: he ranks this hymn first among Lalita tantras, as Srividya is first among mantras with Kadi foremost within it. The nested superlatives locate the text at the summit of its class. Doctrinally it aligns stotra, mantra, and tantra in one hierarchy, guiding devotees to give this recitation central place. The comparison guides seekers overwhelmed by many texts, pointing them to one summit where effort most swiftly meets her grace.", keyPoints: ["Hymn ranked chief among tantras", "Srividya and Kadi paralleled", "Central place claimed for recitation"] },
  { id: "ls-purva-18", number: "Pūrva 18", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "purāṇāṁ śrīpuramiva śaktīnāṁ lalitā yathā । śrīvidyopāsakānāṁ ca yathā devaḥ paraḥ śivaḥ", translation: "As Sripura among cities, as Lalita among powers, and as the god supreme Shiva among those worshipped by Srividya adorers.", commentary: "Hayagrīva answers: three similes fix supreme rank through sacred city, Goddess, and God, each unsurpassed in its order. The verse teaches by analogy, letting known eminences illuminate the hymn's eminence. For devotees it weaves cosmology, theology, and liturgy together, showing the thousand names belong at the apex they already revere. Each analogy draws on devotion readers already hold, transferring settled certainty from city, Goddess, and God to this waiting hymn.", keyPoints: ["Triple analogy for supremacy", "City, Goddess, and God invoked", "Hymn placed at revered apex"] },
  { id: "ls-purva-19", number: "Pūrva 19", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "tathā nāmasahasreṣu parametatprakīrtitam । yathāsya paṭhanāddevī prīyate lalitāmbikā", translation: "So among thousand-named hymns is this proclaimed supreme, since by its recitation the goddess Lalitambika is pleased.", commentary: "Hayagrīva answers: he draws the conclusion that this hymn outranks its peers, with the Mother's pleasure as proof and measure. Supremacy here is relational, grounded in her delight rather than literary merit. Practically it directs choice, that seekers of her favour should prefer this chant above other thousand-name hymns. Pleasing her becomes the true test of a hymn, above metre or erudition, and this text passes that test supremely.", keyPoints: ["Supremacy among name-hymns declared", "Her pleasure as the criterion", "Devotees directed to this chant"] },
  { id: "ls-purva-20", number: "Pūrva 20", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "anyanāmasahasrasya pāṭhānna prīyate tathā । śrīmātuḥ prītaye tasmādaniśaṁ kīrtayedidam", translation: "By reciting another thousand-named hymn she is not so pleased; therefore for the holy Mother's pleasure this should be chanted unceasingly.", commentary: "Hayagrīva answers: comparative efficacy becomes precept, since other recitations please her less, this one deserves constant repetition. The verse turns praise into daily rule. It establishes nityatva in spirit, urging that desire for her love translate into uninterrupted cultivation of these names. The counsel suits daily life, urging practitioners to invest limited time where affection and effect are greatest, rather than scattering effort across lesser praises.", keyPoints: ["Comparative efficacy asserted", "Constant chanting enjoined", "Love expressed through repetition"] },
  { id: "ls-purva-21", number: "Pūrva 21", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "bilvapatraiścakrarāje yo’rcayellalitāmbikām । padmairvā tulasīpuṣpairebhirnāmasahasrakaiḥ", translation: "Whoever worships Lalitambika on the king of chakras with bilva leaves, or with lotuses or tulasi blossoms, together with these thousand names.", commentary: "Hayagrīva answers: he joins floral offerings on the Srichakra to recitation, naming accessible leaves and flowers as fitting media. The verse unites outer puja with verbal praise, neither alone being complete. For householders it shows an attainable rite, that simple leaves offered with the names upon the sacred diagram carry full weight. Even modest gardens supply these offerings, so no devotee need feel excluded from the splendid worship of the throne Goddess.", keyPoints: ["Flowers on Srichakra prescribed", "Bilva, lotus, tulasi named", "Outer offering joined to names"] },
  { id: "ls-purva-22", number: "Pūrva 22", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "sadā prasādaṁ kurute tasya siṁhāsaneśvarī । cakrādhirājamabhyarcya japtvā pañcadaśākṣarīm", translation: "To him the Lady of the Lion-throne ever shows favour; having worshipped the chief of chakras and muttered the fifteen-syllabled formula.", commentary: "Hayagrīva answers: he promises the throne Goddess's continual grace to such worship and sequences worship before mantra repetition. Grace appears as response to ordered devotion rather than arbitrary favour. The verse fixes liturgical order, diagram worship, then root mantra, then hymn, giving practitioners a clear progression. The sequence prevents haste, teaching that praise should follow purification of seat and empowerment of mantra for fullest grace.", keyPoints: ["Throne Goddess's grace promised", "Worship then mantra sequenced", "Liturgical order clarified"] },
  { id: "ls-purva-23", number: "Pūrva 23", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "japānte kīrtayennityamidaṁ nāmasahasrakam । japapūjādyaśaktaścet paṭhennāmasahasrakam", translation: "At the end of muttering one should daily chant this thousand names; and if unable in muttering, worship and the rest, one should recite the thousand names.", commentary: "Hayagrīva answers: he makes the hymn the regular sequel to japa while allowing it as substitute when full rite is impossible. This flexible rule preserves continuity for the busy, aged, or infirm. Doctrinally it shows the names share the essence of mantra and puja, capable of standing for the whole when the whole cannot be performed. Such accommodation keeps vows unbroken across travel, illness, and age, letting the names carry the whole rite when strength wanes.", keyPoints: ["Daily sequel to japa enjoined", "Substitute when rite impossible", "Continuity preserved for all states"] },
  { id: "ls-purva-24", number: "Pūrva 24", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "sāṅgārcane sāṅgajape yatphalaṁ tadāpnuyāt । upāsane stutīranyāḥ paṭhedabhyudayo hi saḥ", translation: "He obtains the fruit of worship with its limbs and muttering with its limbs; in worship, to recite other praises brings prosperity indeed.", commentary: "Hayagrīva answers: he assures that the substitute loses nothing, yielding the full fruit of complete rites, while other hymns serve general welfare. The distinction honours other praises without equating them. Practically it relieves anxiety about omission, teaching that faithful recitation of these names carries the virtue of the entire apparatus. The assurance frees conscientious worshippers from guilt over simplified practice, affirming that love completes what circumstance curtails.", keyPoints: ["Full fruit assured to reciter", "Other hymns for general welfare", "Faithful chanting removes deficiency"] },
  { id: "ls-purva-25", number: "Pūrva 25", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "idaṁ nāmasahasraṁ tu kīrtayennityakarmavat । cakrarājārcanaṁ devyā japo nāmnāṁ ca kīrtanam", translation: "But this thousand names should be chanted as a fixed daily duty; worship of the Goddess on the king of chakras, muttering, and chanting of names.", commentary: "Hayagrīva answers: he elevates the threefold observance to nitya-karma, unavoidable daily obligation rather than optional merit. The verse defines a devotee's minimum: diagram worship, root repetition, and name chanting. It guards against reducing religion to occasional enthusiasm by anchoring love in steady routine. By naming it duty, the teacher lifts chanting above mood, making remembrance as regular as eating and sleeping in a devotee's day.", keyPoints: ["Threefold rite as daily duty", "Worship, japa, chanting combined", "Steadiness over occasional fervour"] },
  { id: "ls-purva-26", number: "Pūrva 26", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "bhaktasya kṛtyametāvadanyadabhyudayaṁ viduḥ । bhaktasyāvaśyakamidaṁ nāmasāhasrakīrtanam", translation: "That much is the devotee's task; the rest the wise know as leading to prosperity; for the devotee this chanting of the thousand names is indispensable.", commentary: "Hayagrīva answers: he separates essentials from auspicious extras, declaring this chanting non-negotiable for devotees. The stark division simplifies decision amid many observances. It teaches prioritization, that when time is short the names must remain, while other flourishes may serve worldly uplift. This clarity simplifies spiritual bookkeeping, letting devotees discern the non-negotiable core amid many attractive optional observances that may otherwise crowd out essentials.", keyPoints: ["Essentials separated from extras", "Name-chanting declared indispensable", "Prioritization taught for devotees"] },
  { id: "ls-purva-27", number: "Pūrva 27", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "tatra hetuṁ pravakṣyāmi śṛṇu tvaṁ kumbhasambhava । purā śrīlalitādevī bhaktānāṁ hitakāmyayā", translation: "I shall tell the reason for this, listen, O pitcher-born; formerly the holy goddess Lalita, wishing the welfare of devotees.", commentary: "Hayagrīva answers: promising the origin story behind the rule, he invokes the Goddess's compassionate motive toward devotees. The verse creates expectancy for revelation of divine authorship. It frames obligation as grace, that necessity rests not on priestly invention but on her own loving provision. Listeners are thus prepared to hear revelation rather than mere rule, since what follows flows from maternal care and not compulsion.", keyPoints: ["Reason for rule promised", "Her welfare-motive invoked", "Obligation grounded in compassion"] },
  { id: "ls-purva-28", number: "Pūrva 28", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "vāgdevatā vaśinyādyāḥ śṛṇudhvaṁ vacanaṁ mama । ", translation: "O speech-goddesses beginning with Vashini, hear my word.", commentary: "The Goddess commands: with brief sovereign address she summons Vashini and her companions to attention. The terseness conveys authority, needing no persuasion before instruction. Narratively it marks the shift from Hayagriva's report to her direct speech, placing the hymn's origin in her own utterance. The moment mirrors royal durbars, where a single sentence from the throne mobilizes entire ranks of servants to creative action.", keyPoints: ["Direct summons to Vagdevis", "Sovereign brevity marks authority", "Divine speech begins the origin"] },
  { id: "ls-purva-29", number: "Pūrva 29", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "bhavatyo matprasādena prollasadvāgvibhūtayaḥ । madbhaktānāṁ vāgvibhūtipradāne viniyojitāḥ", translation: "By my favour you possess unfolded powers of speech; you are appointed to bestow mastery of speech upon my devotees.", commentary: "The Goddess commands: she reminds the speech deities that their eloquence derives from her grace and assigns them its redistribution to devotees. The verse links divine gift to office, power held implies duty to share. It reveals a theology of grace mediated through speech, whereby devotees gain expressive and mantric fluency. It portrays speech itself as delegated divine wealth, so poets and teachers serve as stewards of a power they did not originate.", keyPoints: ["Speech powers traced to her grace", "Office to bless devotees assigned", "Grace mediated through sacred speech"] },
  { id: "ls-purva-30", number: "Pūrva 30", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "maccakrasya rahasyajñā mama nāmaparāyaṇāḥ । mama stotravidhānāya tasmādājñāpayāmi vaḥ", translation: "Knowers of my wheel's secret, devoted to my names, for fashioning my praise therefore I command you.", commentary: "The Goddess commands: citing their knowledge of her chakra mystery and devotion to her names as qualifications, she orders them to compose her hymn. Fitness and task are matched, only insiders can utter the esoteric names. It teaches that sacred composition requires both technical knowing and loving absorption. Only those steeped in diagram, name, and praise are chosen, showing that revelation passes through prepared vessels rather than chance mouths.", keyPoints: ["Qualified deities selected", "Chakra knowledge plus devotion cited", "Command to compose the hymn"] },
  { id: "ls-purva-31", number: "Pūrva 31", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "kurudhvamaṅkitaṁ stotraṁ mama nāmasahasrakaiḥ । yena bhaktaiḥ stutāyā me sadyaḥ prītiḥ parā bhavet", translation: "Fashion a hymn set with my thousand names, whereby praised by devotees my supreme immediate love may come to be.", commentary: "The Goddess commands: she specifies a hymn inlaid with her thousand names aimed at evoking her swift supreme affection when sung by devotees. Authorship, form, and purpose are all divinely fixed. For practice it assures efficacy, since the text was designed by its addressee to please her without delay. Her purpose is frankly relational, seeking the joy of being praised by loving devotees rather than distant ceremonial correctness.", keyPoints: ["Thousand-name hymn specified", "Swift supreme love as aim", "Efficacy assured by her design"] },
  { id: "ls-purva-32", number: "Pūrva 32", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "ityājñaptāstato devyaḥ śrīdevyā lalitāmbayā । rahasyairnāmabhirdivyaiścakruḥ stotramanuttamam", translation: "So ordered by the holy Goddess Lalitamba, the goddesses then made with divine secret names the unsurpassed hymn.", commentary: "Hayagrīva answers: he reports obedient fulfilment, the Vagdevis fashioning an unequalled praise from hidden divine names. The verse closes the commissioning arc, showing word made text. It authenticates the hymn as revealed through authorized speech powers under direct command, not human invention. The result stands beyond rivalry, since heaven's own speech powers wrought it from mystery under her immediate supervision.", keyPoints: ["Divine order obediently fulfilled", "Secret names woven into hymn", "Revealed status authenticated"] },
  { id: "ls-purva-33", number: "Pūrva 33", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "rahasyaṁ nāmasāhasramiti tadviśrutaṁ param । tataḥ kadācitsadasi sthitvā siṁhāsane’mbikā", translation: "As the secret thousand names was that supremely famed; then once Ambika, standing in assembly upon the lion-throne.", commentary: "Hayagrīva answers: he names the work Rahasya-namasahasra and shifts scene to a later court where Ambika sits enthroned. Naming fixes identity while the tableau prepares public promulgation. It teaches that esoteric does not mean hidden forever, but ripened for proclamation at the fitting assembly. The title Rahasya marks intimacy rather than exclusion, naming a closeness that deepens as recitation continues through the years.", keyPoints: ["Secret title famously fixed", "Throne assembly scene set", "Esoteric ripened for proclamation"] },
  { id: "ls-purva-34", number: "Pūrva 34", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "svasevāvasaraṁ prādāt sarveṣāṁ kumbhasambhava । sevārthamāgatāstatra tu vāṇīsraṣṭukoṭayaḥ", translation: "She gave to all an occasion of service, O pitcher-born; assembled there for service were crores of speakers and creators.", commentary: "Hayagrīva answers: describing universal audience granted from the throne, with myriads of Brahma-like creators and Vani powers present. The vast attendance magnifies the coming first recitation. It conveys that her grace is impartially accessible, offering every order of being opportunity for service. No rank is turned away, teaching that her court honours every sincere servant, from cosmic architects to humble singers.", keyPoints: ["Universal audience granted", "Myriads of creators assembled", "Grace offered to all orders"] },
  { id: "ls-purva-35", number: "Pūrva 35", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "lakṣmīnārāyaṇānāṁ ca koṭayaḥ samupāgatāḥ । gaurīkoṭisametānāṁ rudrāṇāmapi koṭayaḥ", translation: "And crores of Lakshmis with Narayanas had come, and crores of Rudras with crores of Gauris.", commentary: "Hayagrīva answers: he continues the census with countless preservative and transformative pairs in attendance. The pairing preserves cosmic balance even in festivity. It suggests the whole pantheon gathers to witness the hymn, endorsing its universal authority. Their presence lends immense cosmic weight, as preservation and dissolution themselves pause in reverence to attend the blessed birth of her eternal praise in full assembly.", keyPoints: ["Countless Vishnu-Lakshmi pairs", "Countless Rudra-Gauri pairs", "Whole pantheon as witness"] },
  { id: "ls-purva-36", number: "Pūrva 36", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "mantriṇīdaṇḍinīmukhyāḥ sevārthaṁ yāssamāgatāḥ । śaktayo vividhākārāstāsāṁ saṁkhyā na vidyate", translation: "With Mantrini and Dandini at the head came powers for service, of many forms; of them there was no counting.", commentary: "Hayagrīva answers: her chief ministers and innumerable varied Shaktis arrive, beyond enumeration. The innumerability stresses her infinite retinue. For meditators it populates Sripura worship with living attendants, reminding that the thousand names resound within a teeming sacred court. Variety without number mirrors her infinite energies, each devotee finding among that shining host a face that answers his own deepest longing with grace.", keyPoints: ["Chief ministers head retinue", "Innumerable varied Shaktis", "Sacred court beyond counting"] },
  { id: "ls-purva-37", number: "Pūrva 37", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "divyaughā mānavaughāśca siddhaughāśca samāgatāḥ । tatra śrīlalitādevī sarveṣāṁ darśanaṁ dadau", translation: "The divine current, the human current, and the current of perfected ones had come; there holy Lalita granted vision to all.", commentary: "Hayagrīva answers: the three lineages of teachers and seekers gather, and she bestows darshana on everyone present. Doctrine and grace meet, lineages authenticate while vision blesses. It models the ideal assembly where teaching authority and direct experience coincide. Gods, humans, and adepts stand peacefully together, dissolving all pride of birth in shared beholding of the one universal Mother in glory.", keyPoints: ["Three lineages assembled", "Universal darshana bestowed", "Authority joined to experience"] },
  { id: "ls-purva-38", number: "Pūrva 38", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "teṣu dṛṣṭvopaviṣṭeṣu sve sve sthāne yathākramam । tataḥ śrīlalitādevīkaṭākṣākṣepacoditāḥ", translation: "Seeing them seated each in his own place in due order, then impelled by the cast of holy Lalita's sidelong glance.", commentary: "Hayagrīva answers: orderly seating precedes a silent signal from her glance that prompts the Vagdevis. Command without words displays sovereign ease. It teaches sensitivity to subtle direction, that advanced devotees move at a hint of her favour rather than awaiting loud orders. The glance-teaching remains a living lesson, that ripened disciples discern her will in quiet signs before explicit words arrive.", keyPoints: ["Orderly seating observed", "Silent glance as signal", "Subtle direction moves devotees"] },
  { id: "ls-purva-39", number: "Pūrva 39", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "utthāya vaśinīmukhyā baddhāṁjalipuṭāstadā । astuvannāmasāhasraiḥ svakṛtairlaṁlitāmbikām", translation: "Rising, those headed by Vashini with folded cupped hands then praised Lalitambika with their own thousand names.", commentary: "Hayagrīva answers: obedient to the glance, the speech goddesses rise reverently and sing their composition before her. First public chanting fulfils the original commission. Practically it exemplifies hymnody as offering, standing, hands folded, voice raised in the presence she inhabits. Folded hands join bodily action to vocal utterance, showing that true praise engages body, breath, and mind together in single reverent uprising.", keyPoints: ["Vagdevis rise reverently", "First chanting before her", "Hymnody modelled as offering"] },
  { id: "ls-purva-40", number: "Pūrva 40", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "śrutvā stavaṁ prasannā’bhūlllitā parameśvarī । te sarve vismayaṁ jagbhurye tatra sadasi sthitāḥ", translation: "Hearing the praise, Lalita the supreme Lady was pleased; all those standing in that assembly were seized with wonder.", commentary: "Hayagrīva answers: her delight confirms success, while the court's amazement attests its surpassing beauty. Divine pleasure validates the text more than any argument. It assures reciters that sincere chanting reproduces that first pleasing, inviting them into the same wonder. Wonder spreads like warming light through the vast court, confirming that genuine devotion delights both its divine object and its human witnesses.", keyPoints: ["Her pleasure confirms the hymn", "Assembly seized with wonder", "Divine delight validates the text"] },
  { id: "ls-purva-41", number: "Pūrva 41", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "tataḥ provāca lalitā sadasyān devatāgaṇān । mamājñayaiva vāgdevyaścakruḥ stotramanuttamam", translation: "Then Lalita spoke to the hosts of gods in assembly; by my order alone the speech goddesses made the unsurpassed hymn.", commentary: "Hayagrīva answers: she publicly claims authorship-by-command, lest any attribute the hymn to independent invention. The declaration secures its revealed authority. It teaches devotees to acknowledge grace behind sacred poetry, tracing eloquence to her mandate. Public acknowledgment prevents all later disputes over origin, firmly anchoring the hymn's authority in her own direct unambiguous testimony for all time and every lineage forever.", keyPoints: ["She claims command-authorship", "Independent invention denied", "Revealed authority publicly secured"] },
  { id: "ls-purva-42", number: "Pūrva 42", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "aṅkitaṁ nāmabhirdivyairmama prītividhāyakaiḥ । tatpaṭhadhvaṁ sadā yūyaṁ stotraṁ matprītivṛddhaye", translation: "Set with divine names that effect my love; recite it ever, all of you, for the increase of my love.", commentary: "Hayagrīva answers: describing the hymn as studded with love-effecting names, she enjoins constant recitation for growth of her affection. Repetition becomes cultivation of relationship. For practice it makes frequency the means, love deepened not by single hearing but by sustained return. Growth of love is offered as an ongoing path, not a single event, inviting lifelong deepening through repeated chanting.", keyPoints: ["Names as love-effecting gems", "Constant recitation enjoined", "Love grown through repetition"] },
  { id: "ls-purva-43", number: "Pūrva 43", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "pravartayadhvaṁ bhakteṣu mama nāmasahasrakam । idaṁ nāmasahasraṁ me yo bhaktaḥ paṭhate sakṛt", translation: "Spread it among devotees, my thousand names; whatever devotee of mine recites this thousand names of mine even once.", commentary: "Hayagrīva answers: she orders dissemination among devotees and begins her promise even for a single recitation. Esotericism now turns missionary within the faithful. It charges every hearer with transmission, making preservation an act of obedience. Even one sincere recitation counts very decisively, opening wide hope for beginners who cannot yet undertake long extended disciplines or arduous vows in this life.", keyPoints: ["Dissemination among devotees ordered", "Single recitation valued", "Transmission charged as obedience"] },
  { id: "ls-purva-44", number: "Pūrva 44", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "sa me priyatamo jñeyastasmai kāmāndadāmyaham । śrīcakre māṁ sadābhyarcya japtvā pañcadaśākṣarīm", translation: "He should be known as most dear to me; to him I grant desires; having ever worshipped me on the holy wheel and muttered the fifteen-syllabled lore.", commentary: "Hayagrīva answers: she promises highest affection and fulfilment of wishes, situating the hymn after diagram worship and root mantra. Hierarchy is preserved even in generosity. It teaches integrated practice, that the names crown rather than replace established worship and japa. Affection and earthly boons advance gracefully together always, showing that she answers both the heart's deep devotion and life's daily legitimate needs.", keyPoints: ["Dearest status promised", "Desires granted to reciter", "Names crown worship and mantra"] },
  { id: "ls-purva-45", number: "Pūrva 45", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "paścānnāmasahasraṁ me kīrtayenmama tuṣṭaye । māmarcayatu vā mā vā vidyāṁ japatu vā na vā", translation: "Afterwards for my contentment he should chant my thousand names; whether he worships me or not, whether he mutters the lore or not.", commentary: "Hayagrīva answers: she commends post-japa chanting for her satisfaction, then extends the invitation beyond formal worshippers and initiates. Compassion widens access without abolishing the ideal order. Pastorally it keeps the door open, that even the ritually unqualified may approach through loving recitation. The widening embrace comforts the irregular and uninitiated, assuring them that love's chant is never rejected for technical lack.", keyPoints: ["Post-japa chanting commended", "Access widened beyond ritualists", "Compassion opens the door"] },
  { id: "ls-purva-46", number: "Pūrva 46", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "kīrtayennāmasahasramidaṁ matprītaye sadā । matprītyā sakalān kāmāṁllabhate nātra saṁśayaḥ", translation: "He should ever chant this thousand names for my love; through my love he obtains all desires, no doubt in this.", commentary: "Hayagrīva answers: she restates the simple rule and seals it with certainty, love gained through chanting yields all longings. Means and end are both love, desires fulfilled as byproduct. It counsels trustful persistence, doubting neither her responsiveness nor the sufficiency of the names. Calm certainty replaces anxious bargaining, for when her love itself is firmly secured, all subsidiary gains follow without further calculation.", keyPoints: ["Ever chanting for her love", "All desires through her love", "Doubt explicitly removed"] },
  { id: "ls-purva-47", number: "Pūrva 47", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "iti śrīlaliteśānī śāsti devānsahānugān । ", translation: "Thus holy Laliteshani instructs gods with their followers.", commentary: "Hayagrīva answers: he closes her direct address as instruction to gods together with their retinues. The summary verse marks the end of quoted divine speech. It confirms universal promulgation, that not a few specialists but the whole divine assembly received the charge. Retinues are included with their lords, so that teachings permeate entire hierarchies rather than resting with solitary chiefs.", keyPoints: ["Divine instruction summarized", "Whole assembly as recipient", "Quoted speech formally closed"] },
  { id: "ls-purva-48", number: "Pūrva 48", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "tadājñayā tadārabhya brahmaviṣṇumaheśvarāḥ । śaktayo mantriṇīmukhyā idaṁ nāmasahasrakam", translation: "By her command, from then onward Brahma, Vishnu, and Maheshvara, the powers headed by Mantrini, this thousand names.", commentary: "Hayagrīva answers: he reports compliance beginning at once, the great male gods and leading Shaktis taking up the hymn. Heaven itself becomes the first congregation of reciters. It models obedience across hierarchies, showing even supreme gods submit to her order and join the chant. The highest gods leading the chorus encourages humility in human reciters, who join a chant already sung in heaven.", keyPoints: ["Great gods take up chanting", "Leading Shaktis join obedience", "Heaven as first congregation"] },
  { id: "ls-purva-49", number: "Pūrva 49", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "paṭhanti bhaktyā satataṁ lalitāparituṣṭaye । tasmādavaśyaṁ bhaktena kīrtanīyamidaṁ mune", translation: "Recite with devotion ever for Lalita's delight; therefore by a devotee must this be chanted, O sage.", commentary: "Hayagrīva answers: continual devout recitation for her joy becomes the stated practice, whence he draws the necessity for Agastya. Precedent hardens into precept. For listeners it removes optionality, that devoteeship itself entails keeping these names alive on the tongue. The pure joy of Lalita is named the true motive, lifting repetition far above mere duty into delighted participation in her own happiness.", keyPoints: ["Ceaseless devout recitation noted", "Necessity drawn for devotees", "Devoteeship entails the chant"] },
  { id: "ls-purva-50", number: "Pūrva 50", section: "Pūrva-pīṭhikā · Upoddhāta", iast: "āvaśyakatve hetuste mayā prokto munīśvara । idānīṁ nāmasāhasraṁ vakṣyāmi śraddhayā śṛṇu", translation: "The reason for its indispensability has been told to you by me, O best of sages; now I shall speak the thousand names; listen with faith.", commentary: "Hayagrīva answers: concluding the frame, he declares the rationale complete and promises the hymn itself, asking faithful hearing. Anticipation peaks as dialogue yields to text. It cues the reciter to shift posture from understanding reasons to reverent reception of the names about to sound. The call to faith tunes the ear inward, that the syllables now approaching may enter a readied and reverent heart.", keyPoints: ["Rationale declared complete", "Thousand names promised next", "Faithful hearing requested"] },
];
